/* ==========================================================================
   7. FEATURE CARDS
   ========================================================================== */
.features-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--s5);
    max-width: 1000px;
    margin: 0 auto;
}

.feature-card {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    box-shadow: var(--sh-1);
    transition: border-color var(--t-base), box-shadow var(--t-base),
                transform var(--t-base);
}

.feature-card:hover {
    border-color: var(--accent);
    box-shadow: var(--sh-3);
    transform: translateY(-4px);
}

.feature-img-wrapper {
    position: relative;
    height: 200px;
    overflow: hidden;
    background-color: var(--canvas-2);
}

.feature-img-wrapper::after {
    content: '';
    position: absolute;
    left: 0; right: 0; bottom: 0;
    height: 45%;
    background: linear-gradient(to top, rgba(10, 31, 34, .35), transparent);
    pointer-events: none;
}

.feature-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 600ms cubic-bezier(.2, .6, .3, 1);
}

.feature-card:hover .feature-img { transform: scale(1.05); }

.feature-badge {
    position: absolute;
    top: var(--s3);
    left: var(--s3);
    z-index: 2;
    padding: 6px 12px;
    background-color: rgba(10, 31, 34, .88);
    color: #FFFFFF;
    border-radius: var(--r-pill);
    font-size: var(--fs-micro);
    font-weight: 700;
    letter-spacing: .06em;
    text-transform: uppercase;
    -webkit-backdrop-filter: blur(4px);
    backdrop-filter: blur(4px);
}

.feature-body {
    display: flex;
    flex-direction: column;
    flex: 1;
    padding: var(--s5);
}

.feature-body h3 {
    margin-bottom: var(--s2);
    font-size: var(--fs-card);
    font-weight: 700;
    color: var(--ink);
}

.feature-body p {
    flex: 1;
    margin-bottom: var(--s5);
    font-size: .95rem;
    color: var(--text-2);
}

.feature-link {
    align-self: flex-start;
    color: var(--accent);
    font-size: .95rem;
    font-weight: 600;
    text-decoration: none;
    transition: color var(--t-fast), transform var(--t-fast);
}

.feature-card:hover .feature-link {
    color: var(--accent-hover);
    transform: translateX(3px);
}

/* ==========================================================================
   8. SERVICE TABS & CARDS
   ========================================================================== */
.service-tabs {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--s2);
    margin-bottom: var(--s7);
}

.tab-btn {
    min-height: 40px;
    padding: 0 var(--s4);
    background-color: var(--surface);
    color: var(--text-2);
    border: 1px solid var(--border);
    border-radius: var(--r-pill);
    font-family: var(--font-sans);
    font-size: var(--fs-sm);
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    transition: background-color var(--t-fast), color var(--t-fast),
                border-color var(--t-fast);
}

.tab-btn:hover {
    border-color: var(--accent);
    color: var(--accent);
}

.tab-btn.active {
    background-color: var(--ink);
    border-color: var(--ink);
    color: #FFFFFF;
}

#services-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
    gap: var(--s5);
}

.service-card {
    display: flex;
    flex-direction: column;
    padding: var(--s5);
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    box-shadow: var(--sh-1);
    transition: border-color var(--t-base), box-shadow var(--t-base),
                transform var(--t-base);
}

.service-card:hover {
    border-color: var(--accent);
    box-shadow: var(--sh-3);
    transform: translateY(-4px);
}

.card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--s3);
    margin-bottom: var(--s4);
}

.service-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    background-color: var(--accent-soft);
    border: 1px solid var(--accent-line);
    border-radius: var(--r-md);
    font-size: 1.25rem;
    line-height: 1;
}

.badge {
    padding: 5px 11px;
    border-radius: var(--r-pill);
    font-size: var(--fs-micro);
    font-weight: 700;
    letter-spacing: .06em;
    text-transform: uppercase;
    white-space: nowrap;
}

.badge-repair   { background-color: var(--badge-repair-bg);   color: var(--badge-repair-fg); }
.badge-cleaning { background-color: var(--badge-cleaning-bg); color: var(--badge-cleaning-fg); }
.badge-montage  { background-color: var(--badge-montage-bg);  color: var(--badge-montage-fg); }

.service-title {
    margin-bottom: var(--s2);
    font-size: var(--fs-card);
    font-weight: 700;
    color: var(--ink);
}

.service-desc {
    flex: 1;
    margin-bottom: var(--s5);
    font-size: .95rem;
    color: var(--text-2);
}

.card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--s3);
    margin-top: auto;
    padding-top: var(--s4);
    border-top: 1px solid var(--border);
}

.service-price {
    font-family: var(--font-display);
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--price);
}

